def patch_ls_integration_metadata(config: RunnableConfig) -> RunnableConfig:
    """Tag a config's metadata with the LangGraph integration source.

    Adds `ls_integration: langgraph` to the config's metadata so external
    observability and tracing tools can attribute execution events to LangGraph.
    An existing value is never overridden.

    Args:
        config: The config to tag. Mutated in place.

    Returns:
        RunnableConfig: The same config, with the integration metadata ensured.
    """
    metadata = config.get("metadata")
    if metadata is None:
        config["metadata"] = metadata = {}
    if LS_INTEGRATION_METADATA_KEY not in metadata:
        metadata[LS_INTEGRATION_METADATA_KEY] = LS_INTEGRATION_METADATA_VALUE
    return config


